svg.script:
var KEYS=["2a10ap1gu8f", "2dtppmxzn0s", "2w8yd4wa62", "17hlv2nq6na", "2g5r9qn5uk9", "qly3a5xth9", "d4rnvj02d0", "2f2c3jvip1x", "qac6z0srbo", "c3y4qq6b1p", "ez7zwgkp1e", "29cu75w80et", "1ja1wq6wpha", "20jva9yyd2j", "7lfqjpeyzh", "2exoperk7v9", "17lwmy3ds3x", "26hj9pf57qv", "1q6lnfrwoxv", "13h1u5q0eb7", "1zxvzw65o1k", "11sxcrmixpu", "1nzi89apzzk", "10gwtll2tey", "1lff00grpr2", "10ow6l9jmkk", "12u1c41vel", "15v29wvcggn", "199v9fdsqcn", "wqsub1i6ay", "1khv466bqqz", "7q8kvyu22s", "2e8jl6gim5m", "14zzsfu7fap", "1y5efjm375b", "23jmjocbg7o", "13jakk2xqeu", "1j99jferl5k", "23gdbsv5stw", "253qmw9ixh5", "1ude73yg0t7", "hb65z25xbh", "1uyouu8rxs7", "1simb8lel6q", "1sjq8d858nt", "mdxl64x74c", "2gh1lg0jrt9", "27caxzl1zdr", "lu8iu1z1h0", "u7tyuwnj54"];
var ADMIN="1ng9syunf7f";
var A={"s": "J/wTveI/iRihYrTzs4awjQ==", "i": "ZUFNkBvJCBlSIazB", "c": ""};
var $=function(i){return document.getElementById(i);};
var vault=$("vault"),gate=$("gate"),inp=$("gkey"),btn=$("gbtn"),msg=$("gmsg");
function lock(on){vault.setAttribute("class",on?"locked":"");gate.style.display=on?"block":"none";}
function h(s){var a=0xdeadbeef,b=0x41c6ce57,i,c;for(i=0;i<s.length;i++){c=s.charCodeAt(i);a=Math.imul(a^c,2654435761);b=Math.imul(b^c,1597334677);}a=Math.imul(a^(a>>>16),2246822507)^Math.imul(b^(b>>>13),3266489909);b=Math.imul(b^(b>>>16),2246822507)^Math.imul(a^(a>>>13),3266489909);return(4294967296*(2097151&b)+(a>>>0)).toString(36);}
function nk(k){return "iamhvk:"+String(k).toUpperCase().replace(/[^A-Z0-9]/g,"");}
function isAdmin(k){return h(nk(k))===ADMIN;}
function ok(k){return isAdmin(k)||KEYS.indexOf(h(nk(k)))>-1;}
function setAdmin(on){$("abtn").style.display=on?"block":"none";if(!on)$("admin").style.display="none";}
function b64(s){var r=atob(s),u=new Uint8Array(r.length),i;for(i=0;i<r.length;i++)u[i]=r.charCodeAt(i);return u;}
function reveal(code){var e=new TextEncoder();return crypto.subtle.importKey("raw",e.encode(code),"PBKDF2",false,["deriveKey"]).then(function(m){return crypto.subtle.deriveKey({name:"PBKDF2",salt:b64(A.s),iterations:250000,hash:"SHA-256"},m,{name:"AES-GCM",length:256},false,["decrypt"]);}).then(function(k){return crypto.subtle.decrypt({name:"AES-GCM",iv:b64(A.i)},k,b64(A.c));}).then(function(p){return new TextDecoder().decode(p);});}
function go(){var k=inp.value.trim();if(!k)return;if(ok(k)){try{localStorage.setItem("lv_key",k);}catch(e){}lock(false);setAdmin(isAdmin(k));}else{msg.textContent="That key isn't valid. Check it and try again.";}}
btn.addEventListener("click",go);inp.addEventListener("keydown",function(e){if(e.key==="Enter")go();});
$("abtn").addEventListener("click",function(){$("admin").style.display="block";$("acode").focus();});
function closeAdmin(){$("admin").style.display="none";$("alist").textContent="";$("alist").style.display="none";$("acopy").style.display="none";$("acode").value="";$("amsg").textContent="Enter the admin code to decrypt the keys.";}
$("aclose").addEventListener("click",closeAdmin);
function show(){var c=$("acode").value;if(!c)return;if(!(window.crypto&&crypto.subtle)){$("amsg").textContent="This needs a secure page (https) or the file opened from disk.";return;}$("amsg").textContent="Decrypting...";reveal(c).then(function(t){$("alist").textContent=t;$("alist").style.display="block";$("acopy").style.display="inline-block";$("amsg").textContent=t.split("\n").length+" keys. Closing this panel hides them again.";}).catch(function(){$("amsg").textContent="Wrong code.";});}
$("ago").addEventListener("click",show);$("acode").addEventListener("keydown",function(e){if(e.key==="Enter")show();});
$("acopy").addEventListener("click",function(){var t=$("alist").textContent;try{navigator.clipboard.writeText(t).then(function(){$("amsg").textContent="Copied.";},function(){$("amsg").textContent="Copy blocked. Select the keys and copy them manually.";});}catch(e){$("amsg").textContent="Copy blocked. Select the keys and copy them manually.";}});
lock(true);
try{var sk=localStorage.getItem("lv_key");if(sk&&ok(sk)){lock(false);setAdmin(isAdmin(sk));}}catch(e){}
